// TH15 Stage 1 midboss wave: MainSub05 (st01.ecl.txt:1047-1093) + MainSub05b/GirlB01
// (1095-1107, 252-310) and Phantom02 (1218-1256).
// Card frame 0 = phase start; source MainSub05 frame 0 lands after OPENING_BUFFER.
const TH15_RING_BALL2: int = 464; // source etSprite type 7
const TH15_RICE: int = 480;       // source etSprite type 8
const TIME_LIMIT: int = 2524;
const OPENING_BUFFER: int = 120;

// ---------------- Phantom02 ----------------

// Source Phantom02_at: one volley after 120+RAND%100 frames; no loop.
// etCountD -> lanes E1/N3/H3/L3, layers E1/N1/H4/L8.
// etSpeedD -> first-layer speed E1/N2/H3/L4, last speed 1 for every rank.
sub phantom_volley() {
    var rank: int = global(GVAR_RANK);
    var lanes: int = 1;
    var layers: int = 1;
    var sp0: fx = 1fx;
    if rank == 1 { lanes = 3; sp0 = 2fx; }
    if rank == 2 { lanes = 3; layers = 4; sp0 = 3fx; }
    if rank == 3 { lanes = 3; layers = 8; sp0 = 4fx; }

    var aim: angle = aim_player(); // etAim mode0 resolves at fire time
    for q in 0..layers {
        var sp: fx = sp0;
        if layers > 1 {
            sp = sp0 + (1fx - sp0) * (q as fx) / ((layers - 1) as fx);
        }
        for i in 0..lanes {
            // Fixed fan F(N,i), 1deg spacing: N=3 order 0, -1deg, +1deg.
            var off: angle = 0deg;
            if lanes == 3 {
                if i == 1 { off = -1deg; }
                if i == 2 { off = 1deg; }
            }
            var a: angle = aim + off;
            // EX ANIM a=1 birth retreat: position -= 4*velocity.
            _ = fire(TH15_RING_BALL2, 6,
                     $self_x - 4fx * sp * cos(a),
                     $self_y - 4fx * sp * sin(a),
                     sp, a, none, none);
        }
    }
}

async sub phantom_at() {
    // Source EX records are ANIM a=1 and SPEEDUP with no parameters; ANIM visuals omitted.
    wait(120 + rand(100));
    phantom_volley();
}

async sub phantom_main() {
    set_invuln(65535);
    set_hurtbox(14fx); // setHurtbox(28,28)
    set_hitbox(8fx);   // setHitbox(16,16)
    spawn phantom_at();
    move_vel(0, 90deg, 1fx, EASE_LINEAR); // moveVel(pi/2, 1)
    wait(140);
    // moveVelTime(120, mode3, pi/2, 0) is superseded by the ellipse set in the same
    // source frame; the first move_vel_xy below cancels it before it can move the enemy.
    move_vel(120, 90deg, 0fx, EASE_QUART_IN);
    // moveEllipseRel(RANDRAD, 2deg, 0, 0, ABS_ANGLE, ratio=0):
    // beta = ABS_ANGLE = pi/2, ratio 0 -> x = cx - r*sin(theta-90deg), y = cy.
    var cx: fx = $self_x;
    var cy: fx = $self_y;
    var theta: int = rand(65536) - 32768; // RANDRAD
    var px: fx = cx;
    var k: int = 1;
    while k <= 90 {
        var r: fx = 40fx;                       // EllipseRelTime: r 0 -> 40 over 60 ticks
        if k < 60 { r = (40fx * (k as fx)) / 60; }
        theta = theta + 364;                    // omega 2deg per frame
        var nx: fx = cx - r * sin((theta - 16384) as angle);
        move_vel_xy(0, nx - px, 0fx, EASE_LINEAR); // integration ends at P(k)
        px = nx;
        wait(1);
        k = k + 1;
    }
    move_vel(0, 270deg, 0fx, EASE_LINEAR);      // moveVel(-pi/2, 0)
    move_vel(120, 270deg, 1fx, EASE_QUART_IN);  // moveVelTime(120, mode3, -pi/2, 1)
    loop { wait(1000); }
}

sub phantom_pair(x: int) {
    _ = spawn_enemy(x as fx, -24fx, 110, 0, 0, 0, phantom_main);
    _ = spawn_enemy((0 - x) as fx, -24fx, 110, 0, 0, 0, phantom_main);
}

// ---------------- GirlB01 ----------------

// Source GirlB01_at fixed fan, mode1, alpha=pi/2, delta=20deg.
// etCountD -> lanes E1/N1/H1/L2, layers 1. etSpeedD -> speed E1.2/N1.6/H2.2/L4.2.
sub girl_fan(offx: fx, lanes: int, sp: fx) {
    for i in 0..lanes {
        // F(2,0)=+10deg, F(2,1)=-10deg; a single lane fires straight down.
        var a: angle = 90deg;
        if lanes == 2 {
            if i == 0 { a = 100deg; } else { a = 80deg; }
        }
        // EX ANIM a=1 birth retreat: position -= 4*velocity.
        _ = fire(TH15_RICE, 6,
                 $self_x + offx - 4fx * sp * cos(a),
                 $self_y - 4fx * sp * sin(a),
                 sp, a, none, none);
    }
}

async sub girl_at() {
    wait(60);
    var rank: int = global(GVAR_RANK);
    var waves: int = 3;
    var gap: int = 20;
    var lanes: int = 1;
    var sp: fx = 1.2fx;
    if rank == 1 { waves = 8; sp = 1.6fx; }
    if rank == 2 { waves = 60; gap = 10; sp = 2.2fx; }
    if rank == 3 { waves = 300; gap = 10; lanes = 2; sp = 4.2fx; }
    for w in 0..waves {
        girl_fan(-8fx, lanes, sp); // etOn(0), offset (-8,0)
        girl_fan(8fx, lanes, sp);  // etOn(1), offset (+8,0)
        wait(gap);
    }
}

async sub girl_main() {
    set_invuln(65535);
    set_hurtbox(16fx); // setHurtbox(32,32)
    set_hitbox(12fx);  // setHitbox(24,24)
    spawn girl_at();
    move_vel(0, 90deg, 2.3fx, EASE_LINEAR);  // moveVel(pi/2, 2.3)
    move_vel(80, 90deg, 0fx, EASE_QUAD_IN);  // moveVelTime(80, mode1, keep angle, 0)
    wait(180);
    var ang: angle = aim_player();           // %ANGLE_PLAYER at this moment
    move_vel(0, ang, 0fx, EASE_LINEAR);      // moveVel(ANGLE_PLAYER, 0)
    move_vel(80, ang, 1fx, EASE_QUAD_IN);    // moveVelTime(80, mode1, keep angle, 1)
    wait(60);
    loop { wait(1000); }
}

// Source MainSub05b: six GirlB01 spawned at 0/60/180/240 relative frames.
async sub mainsub05b() {
    _ = spawn_enemy(128fx, -24fx, 600, 0, 0, 0, girl_main);
    _ = spawn_enemy(-128fx, -24fx, 600, 0, 0, 0, girl_main);
    wait(60);
    _ = spawn_enemy(0fx, -24fx, 600, 0, 0, 0, girl_main);
    wait(120);
    _ = spawn_enemy(96fx, -24fx, 600, 0, 0, 0, girl_main);
    _ = spawn_enemy(-96fx, -24fx, 600, 0, 0, 0, girl_main);
    wait(60);
    _ = spawn_enemy(0fx, -24fx, 600, 0, 0, 0, girl_main);
}

// ---------------- wave schedule ----------------

async sub pattern() {
    wait(OPENING_BUFFER);
    // Group A: A=10..50 at source frames 0..120.
    var a: int = 0;
    for ia in 0..5 { a = a + 10; phantom_pair(a); wait(30); }
    // Group B: A=138..178 at 150..270.
    a = 128;
    for ib in 0..5 { a = a + 10; phantom_pair(a); wait(30); }
    a = a - 128; // 50
    // Group C: A=60..100 at 300..420.
    for ic in 0..5 { a = a + 10; phantom_pair(a); wait(30); }
    // Group D overlaps MainSub05b (launched at source frame 450); A=110..190.
    spawn mainsub05b();
    for id in 0..9 { a = a + 10; phantom_pair(a); wait(30); }
    wait(60);
}

// ---------------- training shell ----------------

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
